	(181, 'Software Development Intern', 'RareMinds Technologies Pvt. Ltd.', 'https://rareminds.in/assets/logo.png', 'Internship', 'Bengaluru, Karnataka', 'On-site', NULL, '0–1 years', '"HTML, CSS, JavaScript, React (basic), Node.js (basic), Git"', 'We are looking for a passionate Software Development Intern who is eager to learn and work on real-world web applications. The intern will assist in building frontend and backend features while gaining exposure to modern development practices.', NULL, '2026-01-30 00:00:00+00', true, '2026-01-01 09:25:00.393793+00', '2026-01-23 04:47:30.352759+00', 'Engineering', 'Entry', 120000, 239999, 'open', '2026-01-01 09:24:59.287+00', NULL, '["Basic knowledge of JavaScript and web development", "Familiarity with React or any frontend framework", "Understanding of Git and version control", "Good learning attitude and problem-solving mindset", "Currently pursuing or recently completed a degree in Computer Science or related field"]', '["Assist in developing frontend and backend modules", "Write clean and maintainable code under guidance", "Participate in code reviews and team meetings", "Debug issues and improve existing features", "Learn and follow software development best practices"]', '"Mentorship from senior developers\nInternship completion certificate\nHands-on project experience\nFlexible learning environment\nPotential full-time opportunity"', 0, 0, 0, '902d03ef-71c0-4781-8e09-c2ef46511cbb', 'Software Development Intern', '902d03ef-71c0-4781-8e09-c2ef46511cbb', '[-0.018505769,0.0097520985,0.0061240857,0.021710029,0.014326298,-0.029836778,0.010611212,0.07095813,0.01230622,0.017751142,0.013629719,-0.0143495165,-0.009519906,-0.01873796,0.03336611,0.04267704,0.002397391,-0.033807274,-0.03229802,0.047553092,0.03496824,-0.004368128,0.049457073,0.02751485,0.06427097,-0.0037789382,-0.013769034,0.05015365,0.01845933,-0.005459434,0.057816014,-0.016009696,0.006983199,0.02811855,0.047738846,0.02491429,0.04885337,0.0018140065,0.0040720818,-