	('4c66f586-1c30-4748-9c67-554eecbb29e3', '71c61571-eec3-43d5-83f7-fc772b176b84', 'Crowd Density Detection Using CCTV', 'The EyesOn – Crowd Density Detection Using CCTV is an AI-based surveillance system that monitors crowd density in real time using CCTV footage. It uses Computer Vision, Deep Learning, and YOLO to detect and count people accurately. The system classifies crowd levels as low, medium, or high and generates alerts when safety limits are exceeded. It helps improve public safety, surveillance efficiency, and crowd management.', 'ongoing', NULL, NULL, '', '{}', '', '', 'pending', '2026-09-28 09:25:47.546938+00', '2026-09-28 18:01:07.077875+00', '', '', '', '', true, 'college_admin', NULL, NULL, NULL, NULL, NULL, '', '[0.04660034,-0.020233154,0.00730896,0.029510498,-0.03137207,0.0037250519,-0.0034255981,0.013832092,-0.027755737,0.014602661,0.035369873,-0.025512695,-0.015289307,-0.015182495,0.04660034,-0.014778137,-0.008956909,-0.0077438354,0.0035552979,-0.029327393,-0.009239197,0.031677246,0.011390686,-0.005054474,-0.0037612915,-0.07336426,0.02281189,0.0259552,0.027267456,0.025878906,0.031677246,-0.026428223,-0.04019165,-0.035949707,-0.00029873848,0.003288269,-0.008491516,0.04324341,-0.004623413,-0.00982666,0.017181396,-0.012275696,0.023529053,-0.013999939,-0.03302002,-0.06933594,0.023498535,0.008354187,-0.011650085,0.060791016,-0.012771606,0.019378662,-0.037261963,0.0027980804,-0.02671814,-0.019332886,-0.020736694,0.06768799,0.021224976,0.0058937073,0.057525635,-0.0070495605,0.050231934,0.018966675,0.022399902,-0.001449585,-0.07733154,-0.015129089,0.011833191,0.009063721,0.013473511,-0.022506714,0.015426636,-0.0066947937,0.022140503,-0.0041389465,-0.02659607,0.01524353,-0.043121338,-0.0068588257,0.05911255,-0.024887085,-0.06549072,0.050109863,0.008293152,-0.080444336,-0.015098572,-0.027999878,-0.04324341,0.03503418,-0.03744507,0.05670166,0.018844604,0.012878418,0.006122589,0.0048828125,0.027038574,-0.017791748,0.047454834,0.02645874,-0.014816284,0.004138