	('409dd77e-a723-4add-a7dd-148683a790a0', '03e32968-c238-4e59-9986-d7a9f618dc40', 'Virtual Air Writing System Using Kannada Characters', 'Developed a computer vision-based system that allows users to write Kannada characters through hand movements in the air without using a physical keyboard or touchscreen. The system detects hand movements using a camera and MediaPipe, tracks the writing path, and uses CNN-based recognition to identify Kannada characters.', 'ongoing', '2026-06-22', '2026-09-10', 'Jun 2026 - Sep 2026', '{Python,OpenCV,MediaPipe,CNN,TensorFlow/Keras,HTML,CSS,JavaScript,MySQL.}', '', '', 'pending', '2026-09-28 09:36:03.40283+00', '2026-09-28 18:01:10.045545+00', '', '', '', '', true, 'college_admin', NULL, NULL, NULL, NULL, NULL, 'Python Developer', '[0.0065612793,-0.010520935,0.03945923,-0.010894775,-0.01687622,-0.06124878,0.009864807,0.038970947,-0.0357666,0.046325684,0.030776978,-0.014152527,-0.05923462,-0.02130127,0.032226562,0.02230835,-0.027542114,-0.018875122,-0.0289917,0.023284912,0.003648758,-0.016830444,0.009506226,0.029891968,0.06161499,-0.03955078,-0.022872925,0.027740479,0.008377075,0.0037670135,-0.010612488,-0.03289795,-0.0105896,-0.03829956,-0.0037765503,0.0041007996,-0.007347107,-0.006263733,-0.048614502,0.002872467,0.011207581,-0.0068511963,0.009284973,0.022644043,-0.04876709,0.04989624,-0.048217773,0.0440979,-0.017562866,0.039520264,-0.043395996,0.008338928,-0.024749756,0.02192688,-0.0049819946,-0.048553467,-0.010543823,0.025161743,-0.0073242188,-0.03237915,0.052581787,-0.03878784,0.011146545,0.02986145,-0.044647217,0.004886627,-0.044677734,-0.012916565,-0.010848999,0.00042009354,0.011398315,0.024108887,-0.00907135,-0.018447876,-0.023529053,-0.033996582,-0.020706177,0.032440186,0.016326904,0.015586853,-0.009544373,-0.007446289,0.014709473,0.031280518,-0.009780884,-0.017425537,-0.0015592575,-0.015731812,-0.038604736,-0.015464783,-0.033569336,0.04638672,0.011154175,0.02671814,0.048614502,0.041168213,0.0055885315,-0.03753662,0.028717041