	('aa51d00a-c1e8-444f-9dd8-e564115b6fbb', '80bf7c76-5e3d-400f-819d-2ac5d6e69ce8', 'A Study of Employee Attrition in Maini Precision Products Limited', 'The project “A Study of Employee Attrition in Maini Precision Products Limited” analyzes the factors that influence employees to leave the organization. It examines aspects such as job satisfaction, career growth, salary, workplace conditions, management, and employee engagement. The study uses employee data and survey responses to identify major causes of attrition and understand their impact on the organization. It also provides recommendations and retention strategies to reduce employee turnover.', 'ongoing', NULL, NULL, '', '{}', '', '', 'pending', '2026-09-28 09:33:59.204029+00', '2026-09-28 18:01:08.178494+00', '', '', '', '', true, 'college_admin', NULL, NULL, NULL, NULL, NULL, '', '[0.0234375,0.036590576,0.038146973,-0.020004272,-0.033416748,-0.009597778,0.027679443,0.0047569275,0.019378662,0.019165039,0.03829956,-0.051239014,-0.07385254,-0.029510498,0.024261475,0.009048462,-0.013748169,-0.052368164,-0.0158844,0.04711914,0.060821533,0.06970215,0.0234375,0.015403748,0.035003662,-0.002603531,-0.037994385,-0.01158905,0.02178955,-0.027755737,0.050598145,-0.018081665,-0.009567261,-0.0071105957,-0.031021118,0.0073280334,0.04321289,0.012176514,0.009216309,-0.035339355,-0.010551453,0.01285553,0.0040626526,0.031173706,0.012794495,-0.0043754578,-0.0062026978,0.023376465,0.049560547,0.040039062,-0.057739258,-0.030288696,0.027053833,-0.0037879944,-0.005542755,0.011642456,0.013008118,0.009094238,-0.011199951,0.005996704,0.013404846,-0.040618896,0.044921875,0.027832031,-0.016357422,0.010025024,-0.021240234,0.03665161,0.011512756,-0.022155762,0.07244873,-0.015853882,-0.020584106,0.014595032,-0.01423645,-0.06982422,0.0074272156,0.0026988983,-0.027328491,0.034240723,0.047668457,0.0017766953,0.046203613,0.02696228,-0.04660034,-0.017852783,-0.027008057,-0.05609131,-0.06616211,-0.014709473,-0.074523926,-0.00053167343,0.012390137